class WM_OT_val_event_probe(bpy.types.Operator):
 bl_idname='wm.val_event_probe'
 bl_label='Validation Event Probe'
 def invoke(self,context,event):
  context.window_manager.modal_handler_add(self)
  return {'RUNNING_MODAL'}
 def modal(self,context,event):
  native_events.append(dict(type=event.type,value=event.value,ctrl=event.ctrl,shift=event.shift,alt=event.alt))
  if event.type=='Z':
   (ROOT/'redo-native-events.json').write_text(json.dumps(native_events,indent=2))
   return {'FINISHED','PASS_THROUGH'}
  return {'PASS_THROUGH'}
bpy.utils.register_class(WM_OT_val_event_probe)
with timeline_context(): result=sorted(bpy.ops.wm.val_event_probe('INVOKE_DEFAULT'))
